import {num} from './core.mjs';
import {renderChartBoard} from './charts.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const n=(v,d=0)=>num(v)?v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const hrs=v=>num(v)?n(v/60,1):'—';
const date=s=>s?new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}):'Unavailable';
const colors=['#4f008c','#ff375e','#a7a0b2'];
function coverage(s){return !s.covered?'Outside source coverage':s.partial?'Partial source coverage':'Within source date range';}
function subtitle(report){return `${report.definition.impact==='NSA'?'Non-service affected · impact other than Outage':'Services affected · Outage'} · ${report.profile.name||'Report criteria'}`;}
function seriesHeader(report){return `<div class="report-series">${report.series.map((s,i)=>`<div class="report-series-item ${i===0?'current':''}"><span class="report-series-label"><i style="background:${colors[i]}"></i>${i===0?'Review period':i===1?'Comparison':'Earlier comparison'}</span><b>${esc(s.range?.label||'Week unavailable in this year')}</b><span>${s.range?date(s.range.start)+' – '+date(s.range.end):'Calendar has no matching week'}</span><small class="${s.partial?'partial':''}">${coverage(s)} · ${n(s.summary?.tickets)} tickets</small></div>`).join('')}</div>`;}
function tickets(report){const rows=report.now.rows.slice().sort((a,b)=>b.created_date.localeCompare(a.created_date)).slice(0,10);return `<section class="panel"><div class="panel-title"><div><h2>Ticket traceability</h2><p>Latest 10 records in the review period · every KPI can be traced to its source</p></div><button class="text-button" data-go="tickets">Open ticket register →</button></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Ticket / COW</th><th>Region / district</th><th>Created</th><th>Root cause</th><th class="right">Restoration hrs</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-link" data-ticket="${esc(r.id)}">${esc(r.ticket_number)}</button><span class="subline">${esc(r.site_id)}</span></td><td>${esc(r.region)}<span class="subline">${esc(r.district)}</span></td><td>${date(r.created_date)}</td><td>${esc(r.root_cause)}</td><td class="right">${hrs(r.duration_minutes)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching source records.</td></tr>'}</tbody></table></div></section>`;}
export function renderReport(report,state,meta){
  const s=report.now.summary;
  return `<div class="section-heading bi-page-heading"><div><h2>${esc(report.now.range?.label||'Period unavailable')}</h2><p>${esc(subtitle(report))}</p></div><span class="period-badge ${report.now.partial?'partial':''}">${report.now.partial?'Partial coverage':'Power BI chart view'}</span></div>${seriesHeader(report)}
  ${report.now.partial||report.prev.partial?'<div class="report-coverage-note">One or more periods have partial source coverage. The date ranges above show the available comparison.</div>':''}
  ${renderChartBoard(report,state,meta)}
  <div class="report-metrics bi-supporting-metrics"><div><b>${n(s?.sites)}</b><span>COWs with tickets</span></div><div><b>${n(s?.repeatSites)}</b><span>COWs with 2+ tickets</span></div><div><b>${hrs(s?.mttr)} <small>hrs</small></b><span>Mean recorded restoration</span></div><div><b>${n(s?.slaCompliance,1)}<small>%</small></b><span>Source SLA compliance · ${n(s?.slaEligible)} eligible</span></div></div>
  <details class="bi-source-register"><summary>Source ticket records <span>Trace this review to individual tickets</span></summary>${tickets(report)}</details>
  <div class="report-basis"><b>Calculation basis</b><span>Charts use the saved Power BI page and visual criteria. Ticket volume counts filtered rows; restoration hours use recorded minutes ÷ 60. Change lines use the labelled right axis. Source SLA compliance is shown separately from ticket-change measures.</span><button class="text-button" data-go="formulas">Inspect formulas & criteria →</button></div>`;
}
export function renderFormulaAudit(audit,profiles){
  if(!audit)return '<section class="panel empty">Formula audit is unavailable. Reload the page to retry.</section>';
  if(audit.private)return `<section class="panel"><div class="panel-title"><div><h2>Power BI formula audit</h2><p>The complete extraction is available in the private review workspace.</p></div></div><div class="prose"><p>All five original report pages, 123 DAX measures, 88 calculated columns and 13 calculated tables were extracted. Original report metadata is kept with the private platform.</p><p><a class="button primary" href="https://stc-cow-performance-review.eng-altieb.chatgpt.site/#formulas">Open private formula audit</a></p><p>For a separate private deployment, run scripts/extract_powerbi.py on your PBIX and copy its generated formula-audit.json into dist.</p></div></section>`;
  return `<div class="audit-intro"><div><span class="eyebrow">POWER BI MODEL REVIEW</span><h2>From report logic to operational decisions</h2><p>Every original page and expression is recorded below. Live comparisons use selectable periods; legacy inconsistencies remain visible in this audit.</p></div><a class="button primary" href="formula-audit.json" download>Download full extraction</a></div><div class="report-metrics"><div><b>${audit.page_count}</b><span>Original report pages</span></div><div><b>${audit.measure_count}</b><span>DAX measures</span></div><div><b>${audit.calculated_column_count}</b><span>Calculated columns, including date tables</span></div><div><b>${audit.calculated_table_count}</b><span>Calculated tables</span></div></div>
  <section class="panel"><div class="panel-title"><div><h2>Page criteria</h2><p>SA and NSA scopes are kept separately, as saved in the report</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Dashboard</th><th>Service impact</th><th>Parent TT</th><th>Root cause exclusions</th><th>Comparison</th></tr></thead><tbody>${Object.entries(profiles).filter(([id])=>id!=='yoy').map(([id,p])=>`<tr><td><button class="table-link" data-go="${id}">${esc(p.name)}</button></td><td>${p.impact_mode==='NSA'?'Not Outage (includes Degraded)':'Outage'}</td><td>Blank</td><td><details><summary>${p.excluded_root_causes.length} saved values</summary><p class="exclusion-values">${p.excluded_root_causes.map(esc).join(' · ')||'No root cause exclusions'}</p></details></td><td>${esc({overview:'Review month vs previous two months','weekly-sa':'Review week vs previous two weeks','weekly-nsa':'Review week vs previous two weeks','mom-y':'Same month across three years','wow-y':'Same Sunday-based week across three years'}[id])}</td></tr>`).join('')}<tr><td>YoY (new)</td><td>Outage</td><td>Blank</td><td>Monthly SA exclusions</td><td>Matching YTD through review month</td></tr></tbody></table></div></section>
  <section class="panel audit-findings"><div class="panel-title"><div><h2>Model findings and live behavior</h2><p>These explain differences from the saved report; they are never silently applied as ticket exclusions.</p></div></div><ol>${audit.findings.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>
  ${audit.pages.map(page=>`<details class="panel audit-page"><summary><b>${esc(page.name)}</b><span>${page.visuals.length} visual containers · inspect visual queries and filters</span></summary>${page.visuals.filter(v=>v.select.length).map(v=>`<details class="audit-visual"><summary>${esc(v.title||v.type)} <small>${esc(v.type)}</small></summary><pre>${esc(JSON.stringify({select:v.select,where:v.where,visual_filters:v.visual_filters},null,2))}</pre></details>`).join('')}</details>`).join('')}
  <section class="panel"><div class="panel-title"><div><h2>Original DAX measures</h2><p>Exact expressions from the semantic model · legacy hard-coded names and dates retained</p></div></div>${audit.measures.map(m=>`<details class="audit-formula"><summary>${esc(m.Name)}</summary><pre>${esc(m.Expression)}</pre></details>`).join('')}</section>
  <section class="panel"><div class="panel-title"><div><h2>Calculated columns & tables</h2><p>Includes duration bands, SLA expressions and calendar definitions</p></div></div>${[...audit.calculated_columns,...audit.calculated_tables].map(m=>`<details class="audit-formula"><summary>${esc(m.TableName)}${m.ColumnName?' · '+esc(m.ColumnName):''}</summary><pre>${esc(m.Expression)}</pre></details>`).join('')}</section>
  <section class="panel"><div class="panel-title"><div><h2>Power Query transformations</h2><p>Source folder paths are redacted in this downloadable audit; transformations are preserved.</p></div></div>${audit.power_query.map(m=>`<details class="audit-formula"><summary>${esc(m.TableName)}</summary><pre>${esc(m.Expression)}</pre></details>`).join('')}</section>`;
}
